package com.siam.deviceinfo.database;import androidx.room.*;@Database(entities={UsageRecord.class},version=1,exportSchema=false) public abstract class AppDatabase extends RoomDatabase {@Dao public interface Records {@Insert void add(UsageRecord record);@Query("SELECT * FROM device_records ORDER BY created_at DESC LIMIT 100") java.util.List<UsageRecord> recent();}public abstract Records records();private static volatile AppDatabase INSTANCE;public static AppDatabase get(android.content.Context c){if(INSTANCE==null)synchronized(AppDatabase.class){if(INSTANCE==null)INSTANCE=Room.databaseBuilder(c.getApplicationContext(),AppDatabase.class,"device_info.db").build();}return INSTANCE;}}
